def ortho_edit(alpha, kinds=('attn',)):
    edits={}
    for L in range(24):
        if L in [3,7,11,15,19,23]:
            nm=f'model.language_model.layers.{L}.self_attn.o_proj.weight'
        else:
            nm=f'model.language_model.layers.{L}.linear_attn.out_proj.weight'
        if 'attn' in kinds:
            W=load(nm).float().numpy()
            edits[nm]=W + alpha*np.outer(d, d@W)
        if 'mlp' in kinds:
            nm2=f'model.language_model.layers.{L}.mlp.down_proj.weight'
            W=load(nm2).float().numpy()
            edits[nm2]=W + alpha*np.outer(d, d@W)
    return edits
